\label{unifQ} Let $f_{d,c}(x)=x^d+c\in \mathbb{Q}[x]$. If the $abc$-conjecture is valid, then for sufficiently large degree $d$,
\begin{enumerate}
    \item $f_{d,c}$ has no rational periodic points of exact period greater than 1 except when $c=-1$,
    \item $\# \operatorname{PrePer}(f_{d,c},\mathbb{P}^1(\mathbb{Q}))\leq 4$.  
\end{enumerate}
 Moreover, if we assume the explicit $abc$-conjecture, then the result holds for $d\geq 7.$

\label{period4} 
There are infinitely many $c\in\mathbb{Q}$ such that $f_{4,c}(x)=x^4+c$ has rational periodic points of exact period 2. The parametrization of such $c$ and 2-periodic points $x_1,x_2$ are as follows. The parameter $c$ is in the form  $$\displaystyle c=\dfrac{t^6+4t^3-1}{4t^2}$$ and the 2-periodic points are
$$\displaystyle x_1,x_2=\dfrac{t^2\pm\sqrt{-t^4-2 t}}{2 t},$$ where $-t^4-2 t=y^2$ for some $y\in\mathbb{Q}$.

\label{FermatCatalan}
Let $k,n$ be positive integers such that $n>1$, and $f_{d,c}(x)=x^d+c\in \mathbb{Q}[x]$, where $d=2k$. If $X_1/Z$ and $X_2/Z=f_{d,c}(X_1/Z)$ are rational periodic points of exact period $n$ of $f_{d,c}$ with $c=C/Z^d$, and $X_1/Z, X_2/Z$ and $C/Z^d$ are rational numbers expressed in the lowest terms with integers $X_1,X_2$ and $Z$, then $\gcd(X_1,X_2)=1.$ Moreover, for $n=2$,
\begin{itemize}
    \item[$a)$] $X_1^k+X_2^k=\delta Z_1^{2k-1}$ for some $Z_1\in \mathbb{Z}$ and $\delta\in\{1,2\}$,
    \item[$b)$] if $k$ is odd, then $X_1^k+X_2^k= Z_1^{2k-1}$ for some $Z_1\in \mathbb{Z}.$
\end{itemize}

\label{BVY}\cite{MR2098394}
Let $C\in \{1, 2, 3, 5, 7, 11, 13, 15, 17, 19\}$ and prime number $n> \max\{C,4\}$, then the Diophantine equation
$x^n + y^n = Cz^3$ has no solutions in coprime nonzero integers $x, y$ and $z$ with $|xy| > 1$.

\label{ChimShoreySinha}
 Assume the explicit $abc$-conjecture. For all triples $(a,b,c)$ of coprime integers with $a+b=c$, $abc\neq 0$ and $N=\operatorname{rad}(|abc|)$,
$$\displaystyle \max(|a|,|b|,|c|)<\min (N^{1.72},10N^{1.62991},32N^{1.6}).$$

\label{abclemma}
Assume the $abc-$conjecture. Then, for each $\epsilon>0$, there is $K_{\epsilon}$ such that the system
\begin{align*}
\begin{cases}
X_2^d-X_1^d=(X_3-X_2)Z^{d-1} \neq 0\\
\gcd(X_1,X_2)=1\\
\max(|X_1|,|X_2|,|X_3|)=|X_2|\\
W=\max(|X_1|,|X_2|,|X_3|,|Z|)>1
\end{cases}
\end{align*}
satisfies $d<\log_b(2^{1+\epsilon}K_{\epsilon})+5+4\epsilon$, for all $b\in (1,W]$.
Therefore, the system has no integer solutions for sufficiently large positive integer $d.$\\
Moreover, if we assume the explicit $abc$-conjecture, then the system has no integer solutions for $d\geq 10.$

( Lemma \ref{no12})
Assume to the contrary that there is $r\in \mathbb{Q}$ such that $r$ is a $1_2$-type point of $f_{d,c}$. Thus, $f_{d,c}(r)=-x_0$ for a fixed point $x_0\in \mathbb{Q}$. Since $c=x_0-x_0^d,$ we have $$f_{d,c}(r)=r^d+x_0-x_0^d=-x_0.$$ Thus, $r^d+2x_0-x_0^d=0.$ By Corollary~\ref{ratform}, write $r=\dfrac{R}{Z}$ and $x_0=\dfrac{X_0}{Z}$ in the lowest forms. Thus, $\gcd(X_0,Z)=1=\gcd(R,Z).$ Then
\begin{align}
    \dfrac{R^d}{Z^d}+\dfrac{2X_0}{Z}-\dfrac{X_0^d}{Z^d} &=0 \nonumber\\
    X_0^d-R^d&=2X_0Z^{d-1} \nonumber\\
    X_0^{d-1}-\dfrac{R^d}{X_0}&=2Z^{d-1}.\label{abc_prefix}
\end{align}
Since $X_0$ and $Z$ are integers, $X_0\mid R^d$. We consider 2 cases.\\
\textbf{Case 1.} $X_0$ is odd.\\
Then $R$ is odd (otherwise, $2Z^{d-1}$ is odd).\\
Since $$\gcd(R,2Z)=1=\gcd(X_0,2Z)=\gcd(X_0^{d-1},2Z^{d-1}),$$ we have $\gcd(X_0^{d-1},\dfrac{R^d}{X_0})=1.$ Thus, $ X_0^{d-1},\dfrac{R^d}{X_0}$ and $ 2Z^{d-1}$ are coprime. Assume the $abc$-conjecture with $\epsilon =1$. Then there is a constant $K_1>0 $ such that\\
\begin{align*}
 \max(|X_0^{d-1}|,|\dfrac{R^d}{X_0}|, |2Z^{d-1}|)&< K_1\operatorname{rad}(|X_0^{d-1}\cdot \dfrac{R^d}{X_0}\cdot 2Z^{d-1}|)^2\\
 &\leq K_1\operatorname{rad}(|2X_0RZ|)^2.
\end{align*}
If $|X_0|=\max(|X_0|,|R|,|Z|)>1$, then \\
\begin{align*}
    |X_0^{d-1}|&\leq  \max(|X_0^{d-1}|,|\dfrac{R^d}{X_0}|, |2Z^{d-1}|)\\
       &<K_1\operatorname{rad}(|2X_0RZ|)^2\\
       &\leq K_1\operatorname{rad}(|2X_0^3|)^2.
\end{align*}
\begin{equation*}
        \text{Thus,}\, |X_0^{d-1}|< K_14X_0^6.
\end{equation*}
Therefore, $|X_0^{d-7}|< 4K_1.$
Thus, for sufficiently large $d$, there are no integers solution to Eq.~\ref{abc_prefix}. Similarly, we can yield the same result when $|R|$ and $|Z|$ are the maximum values. Moreover, if we assume the explicit $abc$-conjecture with $\epsilon=1$ and $K_1<1$, the result holds when $d\geq 9.$ For $d=8,$ we check all values $|X_0|,|R|,|Z|\leq 3$. None of the values, except $X_0=R=0$, yields the solution to the equation.\\
\textbf{Case 2.} $X_0$ is even.\\
Since $X_0\mid R^d$, $R$ is even. Consider $$\dfrac{X_0^{d-1}}{2}-\dfrac{R^d}{2X_0}=Z^{d-1}.$$ Since $\dfrac{X_0^{d-1}}{2}$ is an integer, so is $\dfrac{R^d}{2X_0}.$ Since $\gcd(X_0,Z)=1$, $\gcd(\dfrac{X_0^{d-1}}{2},\dfrac{R^d}{2X_0})=1.$ From the previous argument in Case 1 for the tuple $(\dfrac{X_0^{d-1}}{2},\dfrac{R^d}{2X_0},Z^{d-1})$, we can yield the same result in this case.\\
